class Account {
  private double balance;               // encapsulation
  public void deposit(double amt) {
    if (amt > 0) balance += amt;
  }
}
Shape s = new Circle();  s.area();     // run-time polymorphism

class Calc { int add(int a, int b) {…}  double add(double a, double b) {…} } // overload
class Animal { void sound() { print("…"); } }
class Dog extends Animal { @Override void sound() { print("Bark"); } } // override

abstract class Employee {
  protected String name;
  Employee(String n) { name = n; }
  abstract double pay();
}
interface Taxable { double TAX = 0.1; double tax(); }
class Manager extends Employee implements Taxable { … }

// DIP + OCP
interface PaymentMethod { void pay(double amt); }
class UpiPayment implements PaymentMethod { … }
class CardPayment implements PaymentMethod { … }
class Checkout {
  private final PaymentMethod pm;
  Checkout(PaymentMethod pm) { this.pm = pm; }
}

class Engine { void start() {…} }
class Car {
  private final Engine engine = new Engine();  // composition
  void start() { engine.start(); }              // delegation
}
